#include <stdio.h>
#include <string.h>

int L, C;
int black[6][6];
int eligible[6][6];
int match[6][6];
int visited[6][6];

int augment(int r, int c) {
    static const int dr[] = {-1, 1, 0, 0};
    static const int dc[] = {0, 0, -1, 1};

    for (int k = 0; k < 4; k++) {
        int nr = r + dr[k];
        int nc = c + dc[k];

        if (nr < 0 || nr >= L || nc < 0 || nc >= C ||
            !eligible[nr][nc] || visited[nr][nc]) {
            continue;
        }

        visited[nr][nc] = 1;
        if (match[nr][nc] == -1 ||
            augment(match[nr][nc] / C, match[nr][nc] % C)) {
            match[nr][nc] = r * C + c;
            return 1;
        }
    }

    return 0;
}

int main(void) {
    int P;
    scanf("%d %d", &L, &C);
    scanf("%d", &P);

    for (int i = 0; i < P; i++) {
        int x, y;
        scanf("%d %d", &x, &y);
        black[x - 1][y - 1] = 1;
    }

    int count = 0;
    static const int dr[] = {-1, 1, 0, 0};
    static const int dc[] = {0, 0, -1, 1};

    for (int r = 0; r < L; r++) {
        for (int c = 0; c < C; c++) {
            if (black[r][c]) continue;

            for (int k = 0; k < 4; k++) {
                int nr = r + dr[k];
                int nc = c + dc[k];
                if (nr >= 0 && nr < L && nc >= 0 && nc < C &&
                    black[nr][nc]) {
                    eligible[r][c] = 1;
                    count++;
                    break;
                }
            }
        }
    }

    memset(match, -1, sizeof(match));
    int matching = 0;

    for (int r = 0; r < L; r++) {
        for (int c = 0; c < C; c++) {
            if (eligible[r][c] && (r + c) % 2 == 0) {
                memset(visited, 0, sizeof(visited));
                matching += augment(r, c);
            }
        }
    }

    printf("%d\n", count - matching);
    return 0;
}
